// Parse Google Trends RSS
const googleRaw = items[0].json.body || '';
const googleTopics = [];
const titleMatches = googleRaw.matchAll(/<title>([^<]+)<\/title>/g);
for (const m of titleMatches) {
  if (m[1] !== 'Google Trends' && m[1].length > 3) {
    googleTopics.push(m[1].trim());
  }
}

// Parse Reddit
const redditData = items[1].json.data?.children || [];
const redditTopics = redditData
  .filter(p => p.data.score > 5000 && !p.data.over_18)
  .map(p => p.data.title)
  .slice(0, 10);

// Parse YouTube Trending
const ytItems = items[2].json.items || [];
const ytTopics = ytItems
  .map(v => v.snippet?.title || '')
  .filter(t => t.length > 5)
  .slice(0, 10);

// Merge and deduplicate
const allTopics = [...new Set([
  ...googleTopics.slice(0, 10),
  ...redditTopics,
  ...ytTopics
])];

// Score by source diversity (appears in multiple = higher score)
const scored = allTopics.map(topic => {
  let score = 0;
  if (googleTopics.includes(topic)) score += 3;
  if (redditTopics.some(r => r.toLowerCase().includes(topic.toLowerCase()))) score += 2;
  if (ytTopics.some(y => y.toLowerCase().includes(topic.toLowerCase()))) score += 2;
  return { topic, score };
});

scored.sort((a, b) => b.score - a.score);

return [{ json: {
  topics: scored.map(s => s.topic).slice(0, 15),
  timestamp: new Date().toISOString(),
  source_counts: {
    google: googleTopics.length,
    reddit: redditTopics.length,
    youtube: ytTopics.length
  }
}}];

