const raw = items[0].json.content[0].text;
const cleaned = raw.replace(/```json|```/g, '').trim();
let topics;
try {
  topics = JSON.parse(cleaned);
} catch(e) {
  // Fallback extraction
  const match = raw.match(/\[.*\]/s);
  topics = match ? JSON.parse(match[0]) : [];
}

// Sort by score, take top 3
topics.sort((a, b) => b.score - a.score);
const selected = topics.slice(0, 3);

// Add metadata for downstream nodes
return selected.map((t, i) => ({
  json: {
    ...t,
    video_index: i + 1,
    scheduled_for: new Date(Date.now() + i * 4 * 3600000).toISOString(),
    status: 'pending'
  }
}));

